import{_ as r,a0 as p,w as c,s as l,ao as i,I as o,a1 as s,A as n,x as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"如何使用 Watchtower 自动更新正在运行的 Docker 容器 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 Watchtower 自动更新正在运行的 Docker 容器 | LCTT (202208) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 Watchtower 自动更新正在运行的 Docker 容器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 Watchtower 自动更新正在运行的 Docker 容器 | LCTT (202208) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202208/20220727 How To Automatically Update Running Docker Containers Using Watchtower","title":"如何使用 Watchtower 自动更新正在运行的 Docker 容器","tag":"202208","desc":""},"relativePath":"202208/20220727 How To Automatically Update Running Docker Containers Using Watchtower.md","filePath":"[post].md"}'),d={name:"202208/20220727 How To Automatically Update Running Docker Containers Using Watchtower.md"};function h(k,e,u,g,w,b){const t=p("Link");return c(),l("div",null,[e[20]||(e[20]=i('<h1 id="如何使用-watchtower-自动更新正在运行的-docker-容器" tabindex="-1">如何使用 Watchtower 自动更新正在运行的 Docker 容器 <a class="header-anchor" href="#如何使用-watchtower-自动更新正在运行的-docker-容器" aria-label="Permalink to “如何使用 Watchtower 自动更新正在运行的 Docker 容器”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202208/13/171633bitrd5imi953bbbi.jpg" alt=""></p><blockquote><p>使用 Watchtower 自动更新 Docker 容器基础镜像</p></blockquote><p>对开发运维人员来说，保持 Docker 容器为最新版本是重要工作之一。手动更新 Docker 容器是一项耗时的工作。这篇文章解释了 <strong>Watchtower</strong> 是什么，如何安装它，以及在 Linux 中如何 <strong>使用 Watchtower 自动更新正在运行的 Docker 容器</strong> 。</p><h3 id="watchtower-是什么" tabindex="-1">Watchtower 是什么？ <a class="header-anchor" href="#watchtower-是什么" aria-label="Permalink to “Watchtower 是什么？”">​</a></h3><p><strong>Watchtower</strong> 是一款自由开源的应用，用来监控运行中的 Docker 容器，并且当它发现基础镜像被更改后，可以自动的更新容器。</p><p>若 Watchtower 发现一个运行中的容器需要更新，它会以发送 SIGTERM 信号的方式，优雅的结束运行中容器的运行。</p><p>它会下载新镜像，然后以最初部署时使用的方式，重启容器。所有文件会在后台自动下载，因此不需要用户的介入。</p><p>在这份指南中，我们将会明白如何在类 Unix 系统中使用 Watchtower 自动更新正在运行的 Docker 容器。</p><p>我已经在 CentOS 和 Ubuntu 中测试了这份指南，所有的 Linux 发行版中操作过程都一样。</p><h3 id="在-linux-中安装-watchtower" tabindex="-1">在 Linux 中安装 Watchtower <a class="header-anchor" href="#在-linux-中安装-watchtower" aria-label="Permalink to “在 Linux 中安装 Watchtower”">​</a></h3><p>可以通过 Docker 镜像的方式下载 Watchtower 。因此，部署它是小事一桩。在你的 Linux 中安装 Docker 镜像，然后运行 Watchtower 立即开始监控 Docker 容器。</p><p>参考下方指导在基于 PRM 和 DEB 包管理系统中安装 Docker</p>',13)),o("ul",null,[o("li",null,[s(t,{href:"https://ostechnix.com/install-docker-centos/"},{default:n(()=>[...e[0]||(e[0]=[a("如何在 CentOS 中安装 Docker",-1)])]),_:1})]),o("li",null,[s(t,{href:"https://ostechnix.com/install-docker-ubuntu/"},{default:n(()=>[...e[1]||(e[1]=[a("如何在 Ubuntu 中安装 Docker",-1)])]),_:1})]),o("li",null,[s(t,{href:"https://ostechnix.com/docker-desktop-for-linux/"},{default:n(()=>[...e[2]||(e[2]=[a("适用于 Linux 的 Docker 桌面初学者手册",-1)])]),_:1})])]),e[21]||(e[21]=i(`<p>安装 Docker 后，你可以使用以下命令以 <code>root</code> 用户身份部署 Watchtower 容器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># docker run -d --name watchtower -v /var/run/docker.sock:/var/run/docker.sock containrrr/watchtower</span></span></code></pre></div><p>如果你已经安装了 Docker 桌面版，以普通用户运行 Watchtower 容器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ docker run -d --name watchtower -v /var/run/docker.sock:/var/run/docker.sock containrrr/watchtower</span></span></code></pre></div><p>该命令会拉取最新版的 <code>watchtower</code> 镜像，并运行 <code>watchtower</code> 容器。</p><p>输出样例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Unable to find image &#39;containrrr/watchtower:latest&#39; locally</span></span>
<span class="line"><span>latest: Pulling from containrrr/watchtower</span></span>
<span class="line"><span>1045b2f97fda: Pull complete </span></span>
<span class="line"><span>35a104a262d3: Pull complete </span></span>
<span class="line"><span>1a0671483169: Pull complete </span></span>
<span class="line"><span>Digest: sha256:bbf9794a691b59ed2ed3089fec53844f14ada249ee5e372ff0e595b73f4e9ab3</span></span>
<span class="line"><span>Status: Downloaded newer image for containrrr/watchtower:latest</span></span>
<span class="line"><span>91c104ef0e9896e8cd5ff30d9f13e728dbfad66443830ec2ac85dde6d7d37564</span></span></code></pre></div><p><img src="https://ostechnix.com/wp-content/uploads/2022/07/Run-Watchtower-Docker-Container.png" alt="Run Watchtower Docker Container"></p><h3 id="使用-watchtower-自动更新-docker-容器" tabindex="-1">使用 Watchtower 自动更新 Docker 容器 <a class="header-anchor" href="#使用-watchtower-自动更新-docker-容器" aria-label="Permalink to “使用 Watchtower 自动更新 Docker 容器”">​</a></h3><p>在你的系统上，Watchtower 正在和其他容器一起运行。你可以使用一下命令查看运行中的 Docker 容器列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ docker ps</span></span></code></pre></div><p>输出样例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CONTAINER ID   IMAGE                       COMMAND                  CREATED          STATUS          PORTS                                         NAMES</span></span>
<span class="line"><span>91c104ef0e98   containrrr/watchtower       &quot;/watchtower&quot;            14 minutes ago   Up 14 minutes   8080/tcp                                      watchtower</span></span>
<span class="line"><span>f90b462b0712   bitnami/wordpress-nginx:6   &quot;/opt/bitnami/script…&quot;   19 minutes ago   Up 19 minutes   0.0.0.0:80-&gt;8080/tcp, 0.0.0.0:443-&gt;8443/tcp   ostechnix-wordpress-1</span></span></code></pre></div><p>正如上方输出所示，<code>watchtower</code> 容器正在和名为 <code>ostechnix-wordpress-1</code> 的容器一起运行。从现在开始，<code>watchtower</code> 会每隔几分钟会检查该容器。</p><p>如果 Watchtower 发现该容器的基础镜像的任何变化，它会优雅的关闭 <code>ostechnix-wordpress-1</code> 容器，然后使用与最初启动它时使用的相同方式，启动新的镜像。</p><p>类似的，它会自动地每隔几分钟检查所有的运行中容器，并自动更新它们。</p><h3 id="watchtower-如何更新多连接的容器" tabindex="-1">Watchtower 如何更新多连接的容器？ <a class="header-anchor" href="#watchtower-如何更新多连接的容器" aria-label="Permalink to “Watchtower 如何更新多连接的容器？”">​</a></h3><p>在监视多连接容器时，Watchtower 十分智能。</p><p>假设我们现在运行两个容器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ docker ps</span></span></code></pre></div><p>输出样例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CONTAINER ID   IMAGE                       COMMAND                  CREATED          STATUS          PORTS                                         NAMES</span></span>
<span class="line"><span>91c104ef0e98   containrrr/watchtower       &quot;/watchtower&quot;            14 minutes ago   Up 14 minutes   8080/tcp                                      watchtower</span></span>
<span class="line"><span>f90b462b0712   bitnami/wordpress-nginx:6   &quot;/opt/bitnami/script…&quot;   19 minutes ago   Up 19 minutes   0.0.0.0:80-&gt;8080/tcp, 0.0.0.0:443-&gt;8443/tcp   ostechnix-wordpress-1</span></span>
<span class="line"><span>a895f082438a   bitnami/mariadb:10.6        &quot;/opt/bitnami/script…&quot;   20 minutes ago   Up 19 minutes   3306/tcp                                      ostechnix-mariadb-1</span></span></code></pre></div><p><img src="https://ostechnix.com/wp-content/uploads/2022/07/View-Running-Docker-Containers.png" alt="View Running Docker Containers"></p><p>正如你看到的，我们正在运行 <code>ostechnix-wordpress-1</code> 和 <code>ostechnix-mariadb-1</code> 这两个容器。<code>ostechnix-mariadb-1</code> 容器链接到 <code>ostechnix-wordpress-1</code> 容器。</p><p>如果 Watchtower 发现 <code>ostechnix-wordpress-1</code> 容器有个新版本，它会先关闭与之相连接的 <code>ostechnix-mariadb-1</code> 容器 ，然后才会关闭 <code>ostechnix-wordpress-1</code> 容器。</p><p>更新 <code>ostechnix-wordpress-1</code> 容器后，Watchtower 会以正确的顺序，且与最初启动它们时使用的相同方式，重启这两个容器，以便应用程序正确恢复。在我们的例子中，首先启动的是 <code>ostechnix-mariadb-1</code> 容器，然后是 <code>ostechnix-wordpress-1</code> 容器，以确保连接能够继续运行。</p><h3 id="监控特定容器" tabindex="-1">监控特定容器 <a class="header-anchor" href="#监控特定容器" aria-label="Permalink to “监控特定容器”">​</a></h3><p>默认情况下，Watchtower 将监控在它所指向的 Docker 守护进程中运行的所有 Docker 容器。</p><p>不过，你可以像下面这样，通过指定容器名称限制 Watchtower 监视特定的 Docker 容器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ docker run -d --name watchtower -v /var/run/docker.sock:/var/run/docker.sock containrrr/watchtower ostechnix-wordpress-1</span></span></code></pre></div><p>在上方的例子中，<code>watchtower</code> 会忽略其他容器，只监视名为 <code>ostechnix-wordpress-1</code> 的容器更新情况。</p><p>如果你不指定任何参数，Watchtower 会照常监视所有运行中的 Docker 容器。</p><h3 id="发送提示" tabindex="-1">发送提示 <a class="header-anchor" href="#发送提示" aria-label="Permalink to “发送提示”">​</a></h3><p>或许你想收到容器更新的通知。你可以通过电子邮件、Slack 、MSTeams 以及 Gotify 发送通知。</p><p>下面这个例子展示了如何通过电子邮件发送通知。假设你已经设置了 SMTP 服务器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>docker run -d \\</span></span>
<span class="line"><span>  --name watchtower \\</span></span>
<span class="line"><span>  -v /var/run/docker.sock:/var/run/docker.sock \\</span></span>
<span class="line"><span>  -e WATCHTOWER_NOTIFICATIONS=email \\</span></span>
<span class="line"><span>  -e WATCHTOWER_NOTIFICATION_EMAIL_FROM=fromaddress@gmail.com \\</span></span>
<span class="line"><span>  -e WATCHTOWER_NOTIFICATION_EMAIL_TO=toaddress@gmail.com \\</span></span>
<span class="line"><span>  -e WATCHTOWER_NOTIFICATION_EMAIL_SERVER=smtp.gmail.com \\</span></span>
<span class="line"><span>  -e WATCHTOWER_NOTIFICATION_EMAIL_SERVER_PORT=587 \\</span></span>
<span class="line"><span>  -e WATCHTOWER_NOTIFICATION_EMAIL_SERVER_USER=fromaddress@gmail.com \\</span></span>
<span class="line"><span>  -e WATCHTOWER_NOTIFICATION_EMAIL_SERVER_PASSWORD=app_password \\</span></span>
<span class="line"><span>  -e WATCHTOWER_NOTIFICATION_EMAIL_DELAY=2 \\</span></span>
<span class="line"><span>  containrrr/watchtower</span></span></code></pre></div><p>参考下方 Watchtower Github 仓库和 Watchtower 官方主页获取更多信息：</p><h3 id="资料" tabindex="-1">资料 <a class="header-anchor" href="#资料" aria-label="Permalink to “资料”">​</a></h3>`,38)),o("ul",null,[o("li",null,[s(t,{href:"https://github.com/v2tec/watchtower"},{default:n(()=>[...e[3]||(e[3]=[a("Watchtower GitHub",-1)])]),_:1})]),o("li",null,[s(t,{href:"https://containrrr.dev/watchtower/"},{default:n(()=>[...e[4]||(e[4]=[a("Watchtower 主页",-1)])]),_:1})])]),e[22]||(e[22]=o("hr",null,null,-1)),o("p",null,[e[6]||(e[6]=a("via: ",-1)),s(t,{href:"https://ostechnix.com/automatically-update-running-docker-containers/"},{default:n(()=>[...e[5]||(e[5]=[a("https://ostechnix.com/automatically-update-running-docker-containers/",-1)])]),_:1})]),o("p",null,[e[11]||(e[11]=a("作者：",-1)),s(t,{href:"https://ostechnix.com/author/sk/"},{default:n(()=>[...e[7]||(e[7]=[a("sk",-1)])]),_:1}),e[12]||(e[12]=a(" 选题：",-1)),s(t,{href:"https://github.com/lkxed"},{default:n(()=>[...e[8]||(e[8]=[a("lkxed",-1)])]),_:1}),e[13]||(e[13]=a(" 译者：",-1)),s(t,{href:"https://github.com/Donkey-Hao"},{default:n(()=>[...e[9]||(e[9]=[a("Donkey",-1)])]),_:1}),e[14]||(e[14]=a(" 校对：",-1)),s(t,{href:"https://github.com/wxy"},{default:n(()=>[...e[10]||(e[10]=[a("wxy",-1)])]),_:1})]),o("p",null,[e[17]||(e[17]=a("本文由 ",-1)),s(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[15]||(e[15]=[a("LCTT",-1)])]),_:1}),e[18]||(e[18]=a(" 原创编译，",-1)),s(t,{href:"https://linux.cn/"},{default:n(()=>[...e[16]||(e[16]=[a("Linux中国",-1)])]),_:1}),e[19]||(e[19]=a(" 荣誉推出",-1))])])}const x=r(d,[["render",h]]);export{T as __pageData,x as default};
